def mismatch(dy,dx):
    m=[]
    for i in range(30):
        for j in range(30):
            a=g[i,j]; b=g[(i+dy)%30,(j+dx)%30]
            if a!=6 and b!=6 and a!=b: m.append((i,j,a,b))
    return m
